{"explanation":"Compounding n times per year gives you $(1 + 1/n)^n after one year: $2 with annual compounding, about $2.61 with monthly compounding, and about $2.71 with daily compounding. More frequent compounding increases your balance, but the extra gains get smaller. In the limit of continuous compounding, your $1 grows to e dollars—approximately $2.71828, not an unlimited amount.","manimCode":"const heading = new Text({ text: 'More compounding, smaller extra gains', fontSize: 30, color: WHITE });
heading.moveTo([0, 3.2, 0]);
const formula = new MathTex({ latex: 'B_n=\\left(1+\\frac{1}{n}\\right)^n \\quad\\longrightarrow\\quad e\\approx 2.71828' });
await formula.waitForRender();
formula.scale(0.8);
formula.moveTo([0, 2.35, 0]);

const ax = new Axes({ xRange: [0, 52, 13], yRange: [0, 3, 1], xLength: 9, yLength: 3.5, tips: false });
ax.moveTo([-0.6, -0.45, 0]);
const balance = n => Math.exp(n * Math.log1p(1 / n));
const curve = ax.plot(balance, { xRange: [1, 52], color: BLUE, numSamples: 600 });
const ceiling = ax.plot(() => Math.E, { xRange: [0, 52], color: YELLOW });
ceiling.setStrokeWidth(2);
const limitLabel = new Text({ text: 'e dollars', fontSize: 20, color: YELLOW });
limitLabel.moveTo(ax.c2p(45, 2.94));
const axisCaption = new Text({ text: 'Compounding periods per year (n)', fontSize: 21, color: GRAY });
axisCaption.moveTo([-0.8, -2.65, 0]);
const dollarCaption = new Text({ text: 'Balance ($)', fontSize: 20, color: GRAY });
dollarCaption.moveTo([-4.55, 1.6, 0]);

const tickLabels = [];
for (const value of [0, 13, 26, 39, 52]) {
  const tick = new Text({ text: String(value), fontSize: 17, color: GRAY });
  tick.moveTo(ax.c2p(value, -0.17));
  tickLabels.push(tick);
}
for (const value of [1, 2, 3]) {
  const tick = new Text({ text: String(value), fontSize: 17, color: GRAY });
  tick.moveTo(ax.c2p(-2.1, value));
  tickLabels.push(tick);
}

const marker = new Dot({ point: ax.c2p(1, balance(1)), color: BLUE });
let readout = new Text({ text: '1 time/year  →  $2.000000', fontSize: 26, color: BLUE });
readout.moveTo([-1.7, -3.25, 0]);
function selectPeriods(value) {
  const n = Math.max(1, Math.min(52, Math.round(value)));
  marker.moveTo(ax.c2p(n, balance(n)));
  scene.remove(readout);
  readout = new Text({ text: n + (n === 1 ? ' time/year' : ' times/year') + '  →  $' + balance(n).toFixed(6), fontSize: 26, color: BLUE });
  readout.moveTo([-1.7, -3.25, 0]);
  scene.add(readout);
}

await scene.play(new Write(heading), new FadeIn(formula));
scene.add(ax, axisCaption, dollarCaption, ...tickLabels);
await scene.play(new AnimationGroup([new Create(curve), new Create(ceiling)]));
scene.add(limitLabel, marker, readout);
await scene.wait(1);
selectPeriods(2);
await scene.wait(1);
selectPeriods(12);
await scene.wait(1);
selectPeriods(52);

makeHoverable(marker, scene, { hoverScale: 1.5, hoverColor: WHITE });
const controls = new Controls(scene, { position: 'bottom-right', width: 230 });
controls.addSlider({ label: 'Periods per year', min: 1, max: 52, value: 52, step: 1, onChange: selectPeriods });
controls.addButton({ label: 'Annual: n = 1', onClick: () => selectPeriods(1) });
controls.addButton({ label: 'Monthly: n = 12', onClick: () => selectPeriods(12) });
controls.addButton({ label: 'Weekly: n = 52', onClick: () => selectPeriods(52) });
await scene.wait(999999);"}

